  snapSeconds(t){const beat=60/this.song.bpm,den=+this.song.timeline.snap.split('/')[1]||8,step=beat*(4/den);return Math.max(0,Math.round(t/step)*step);}
  trackArray(track=this.selectedTrack){return track==='melody'?this.song.notes:this.song[track];}
  historyState(){return {song:this.song,cry:this.cry,sfx:this.sfx,voiceSettings:this.voiceSettings,selectedTrack:this.selectedTrack,selectedLayer:this.selectedLayer,selectedNote:this.selectedNote,tab:this.tab,experience:this.experience,sfxCategory:this.sfxCategory,selectedSfxNode:this.selectedSfxNode};}
