  restoreHistory(raw){const st=JSON.parse(raw);this.song=this.normalizeSong(st.song);this.cry={...defaultCry(),...(st.cry||{})};this.cry.chain=normalizeCryChain(st.cry?.chain,this.cry.special,st.cry?.fx);this.sfx={...defaultSfx(),...(st.sfx||{})};this.voiceSettings={...defaultVoiceSettings(),...(st.voiceSettings||{})};this.selectedTrack=TRACKS.includes(st.selectedTrack)?st.selectedTrack:'melody';this.selectedLayer=Number.isFinite(+st.selectedLayer)?Math.max(0,+st.selectedLayer):0;this.selectedNote=Number.isFinite(+st.selectedNote)?+st.selectedNote:-1;this.tab=['music','sfx'].includes(st.tab)?st.tab:'music';this.experience=LEVEL[st.experience]!=null?st.experience:this.experience;this.sfxCategory=st.sfxCategory||SFX_BASE[this.sfx.preset]?.category||'Battle';this.selectedSfxNode=st.selectedSfxNode||this.selectedSfxNode||'event';this.generator=null;this.engine.stop();this.playState=null;this.render();if(this.tab==='sfx')this.scheduleSfxRender(0);this.saveAll();}
  undo(){if(!this.history.length){this.status('Nothing to undo');return;}const h=this.history.pop();this.future.push({raw:JSON.stringify(this.historyState()),label:h.label});this.restoreHistory(h.raw);this.status(`Undo · ${h.label}`);}
  redo(){if(!this.future.length){this.status('Nothing to redo');return;}const h=this.future.pop();this.history.push({raw:JSON.stringify(this.historyState()),label:h.label});this.restoreHistory(h.raw);this.status(`Redo · ${h.label}`);}

